<script setup>
import { defineAsyncComponent, onMounted, ref } from 'vue'
import { http, unwrap } from '../services/http.js'
import { canArea, canAction } from '../services/access.js'
import { getStoredUser } from '../services/tokens.js'
const CloudPage=defineAsyncComponent(()=>import('../pages/WhatsappCloudPage.vue'))
const dialog=ref(false),mode=ref('broadcast'),number=ref(''),page=ref(null)
function open(value){mode.value=value;dialog.value=true}
onMounted(async()=>{try{number.value=unwrap(await http.get('/whatsapp-cloud/status')).displayPhoneNumber||''}catch{/* The existing chat remains usable during a status failure. */}})
</script>
<template><section class="cloud-inbox-tools"><div><q-icon name="mdi-whatsapp"/><span>{{number?'+'+number.replace(/\D/g,''):'WhatsApp Cloud'}}</span></div><nav><q-btn v-if="canAction(getStoredUser(),'notifications','send') && canArea(getStoredUser(),'contacts')" flat dense no-caps color="primary" icon="campaign" label="Disparo em massa" @click="open('broadcast')"/><q-btn v-if="canAction(getStoredUser(),'whatsapp_cloud','configure')" flat dense no-caps color="primary" icon="webhook" label="Webhooks" @click="open('webhook')"/></nav><q-dialog v-model="dialog" :maximized="$q.screen.lt.md"><q-card class="cloud-tools-dialog"><header><div class="col"><strong>{{mode==='broadcast'?'Disparos em massa · WhatsApp Cloud':'Webhooks · WhatsApp Cloud'}}</strong><small>{{number?'+'+number.replace(/\D/g,''):'Número oficial'}}</small></div><q-btn flat round icon="refresh" aria-label="Atualizar painel" @click="page?.refresh()"/><q-btn flat round icon="close" aria-label="Fechar ferramentas do Cloud" v-close-popup/></header><CloudPage v-if="dialog" :key="mode" ref="page" tools-mode :initial-tab="mode"/></q-card></q-dialog></section></template>
<style scoped>.cloud-inbox-tools{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:7px 12px;background:#eff7fb;border-bottom:1px solid #d7e6ee;flex:none;min-width:0}.cloud-inbox-tools>div{display:flex;align-items:center;gap:7px;font-size:12px;color:#24516c;min-width:0}.cloud-inbox-tools>div span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cloud-inbox-tools nav{display:flex;gap:4px;flex:none}.cloud-tools-dialog{width:1320px;max-width:97vw;max-height:94dvh;border-radius:20px;overflow:auto}.cloud-tools-dialog>header{position:sticky;top:0;z-index:5;background:white;border-bottom:1px solid #dce8e4;display:flex;align-items:center;padding:14px 20px;gap:10px}.cloud-tools-dialog>header strong,.cloud-tools-dialog>header small{display:block}.cloud-tools-dialog>header strong{font-size:17px;line-height:1.4}.cloud-tools-dialog>header small{font-size:12px;color:#6c857a;margin-top:4px}.cloud-tools-dialog :deep(.page-container){min-height:0!important;padding:20px}.cloud-tools-dialog :deep(.cloud-identity__metadata code){overflow-wrap:anywhere}.cloud-tools-dialog :deep(.q-table__middle){max-width:100%;overflow-x:auto}@media(max-width:600px){.cloud-inbox-tools{align-items:stretch;flex-direction:column;gap:2px}.cloud-inbox-tools nav{display:grid;grid-template-columns:1fr 1fr}.cloud-inbox-tools .q-btn{font-size:11px}.cloud-tools-dialog{border-radius:0;max-width:100vw}.cloud-tools-dialog>header{padding:10px;gap:4px}.cloud-tools-dialog>header strong{font-size:15px}.cloud-tools-dialog :deep(.page-container){padding:12px}}</style>
